  {
    "name": "June master palette",
    "settings": [
      {
        "type": "checkbox",
        "id": "june_palette_enabled",
        "label": "Enable master palette",
        "default": true,
        "info": "Controls theme colours. Photos, payment logos and app-controlled checkout retain their own colours."
      },
      {
        "type": "select",
        "id": "june_palette_preset",
        "label": "Palette preset",
        "default": "orange",
        "options": [
          {
            "value": "orange",
            "label": "20 — Vivid Orange (original)"
          },
          {
            "value": "blue",
            "label": "Electric Blue"
          },
          {
            "value": "red",
            "label": "Signal Red"
          },
          {
            "value": "apricot",
            "label": "Apricot & Lilac"
          },
          {
            "value": "midnight_copper",
            "label": "12 — Midnight & Copper"
          },
          {
            "value": "olive_peach",
            "label": "13 — Olive & Peach"
          },
          {
            "value": "graphite_mint",
            "label": "14 — Graphite & Mint"
          },
          {
            "value": "aubergine_chartreuse",
            "label": "15 — Aubergine & Chartreuse"
          },
          {
            "value": "custom",
            "label": "Custom colours"
          }
        ]
      },
      {
        "type": "paragraph",
        "content": "Choose Custom colours to use the pickers below. Switching presets keeps your custom values saved. June sections can opt out using Use master palette."
      },
      {
        "type": "color",
        "id": "june_palette_bg",
        "label": "Page background and gutters",
        "default": "#FFFFFF"
      },
      {
        "type": "color",
        "id": "june_palette_surface",
        "label": "Secondary surfaces",
        "default": "#F5F5F3"
      },
      {
        "type": "color",
        "id": "june_palette_ink",
        "label": "Main text",
        "default": "#171717"
      },
      {
        "type": "color",
        "id": "june_palette_muted",
        "label": "Muted text",
        "default": "#656565"
      },
      {
        "type": "color",
        "id": "june_palette_accent",
        "label": "Primary accent and buttons",
        "default": "#F56A28"
      },
      {
        "type": "color",
        "id": "june_palette_on_accent",
        "label": "Button text",
        "default": "#171717"
      },
      {
        "type": "color",
